import {loadAxesGrid,scopeAxes} from './lastplanner-axes.mjs';
import {scopeFromGeometry} from './lastplanner-spatial.mjs';
import {calibrate,orientedEdges} from './lastplanner-intelligence.mjs';
export function roomEditor(host,{get,set,esc,onPending,suggestion}){
 let editing=null,dirty=false;
 function render(){const scopes=get(),rooms=[...new Map(scopes.map(s=>[s.roomId,s])).values()];host.innerHTML='<h4>Recintos y superficies</h4>'+rooms.map(r=>`<div class="lpRoomRow"><button type="button" data-room-edit="${esc(r.roomId)}">${esc(r.code)} · ${esc(scopes.filter(s=>s.roomId===r.roomId&&!s.locationOnly).map(s=>s.orientation?'Muro '+s.orientation.label:s.label||s.tipo).join(', ')||'Pendiente de definir superficies')}</button><button type="button" data-room-delete="${esc(r.roomId)}" aria-label="Quitar recinto ${esc(r.code)}">Quitar</button></div>`).join('')+'<div data-room-editor></div>';host.querySelectorAll('[data-room-edit]').forEach(b=>b.onclick=()=>open(b.dataset.roomEdit));host.querySelectorAll('[data-room-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Quitar este recinto y sus superficies?')){set(get().filter(s=>s.roomId!==b.dataset.roomDelete));render();}});}
 async function open(id){if(dirty&&!confirm('¿Descartar los cambios sin aplicar de este recinto?'))return;editing=id;dirty=false;const activeEditor=host.querySelector('[data-room-editor]');[...host.querySelectorAll('[data-room-edit]')].find(b=>b.dataset.roomEdit===id)?.parentElement.after(activeEditor);activeEditor.textContent='Cargando superficies…';const all=get(),original=all.filter(s=>s.roomId===id),base=original[0],boundary=base.roomBoundary|| (base.geometry?.type==='polygon'?base.geometry:null),grid=await loadAxesGrid(base.level).catch(()=>null);if(editing!==id)return;const cal=grid&&calibrate(grid.grid,grid.reference),choices=[],boundaries=[...new Map(original.flatMap(s=>s.roomBoundaries||[s.roomBoundary||(s.geometry?.type==='polygon'?s.geometry:null)]).filter(Boolean).map(g=>[JSON.stringify(g),g])).values()];
 for(const boundary of boundaries){const edges=orientedEdges(boundary.points,cal);
 for(const edge of edges){const room={id:base.roomId,code:base.code,name:base.name,level:base.level};const scope=scopeFromGeometry(room,'muros',{type:'line',points:edge.points},base.source||{},grid?.grid,base.source?.quality,'Muro '+edge.label+' · contorno por verificar');choices.push({...scope,roomBoundary:boundary,roomBoundaries:boundaries,orientation:edge,level:base.level,ejes:scopeAxes(scope,grid?.grid,grid?.reference)});}
 for(const type of ['cielos','pavimentos'])if(boundary){const room={id:base.roomId,code:base.code,name:base.name,level:base.level},s=scopeFromGeometry(room,type,boundary,base.source||{},grid?.grid,base.source?.quality,type==='cielos'?'Cielo · proyección en planta':'Pavimento');choices.push({...s,roomBoundary:boundary,roomBoundaries:boundaries,ejes:scopeAxes(s,grid?.grid,grid?.reference)});}
 }
 // Retain previously delimited partial surfaces and historic whole-room meanings explicitly.
 for(const s of original.filter(s=>!s.locationOnly))if(!choices.some(c=>c.id===s.id))choices.push(s);
 const selected=new Set(original.filter(s=>!s.locationOnly).map(s=>s.id)),editor=host.querySelector('[data-room-editor]');editor.innerHTML=`<h4>Recinto ${esc(base.code)}</h4><p>¿Qué superficie intervendrás?</p>${suggestion?.()?`<p>Superficie sugerida por la partida: ${esc(suggestion())}. Confirma los elementos que intervendrás.</p>`:''}<p class="lpCycleNote">Los muros identificados son tramos de contorno, pendientes de verificar como elementos físicos. No se calculan alturas ni m² de muros.</p>${['muros','cielos','pavimentos','recinto'].filter(type=>type!=='recinto'||choices.some(c=>c.tipo==='recinto')).map(type=>`<details data-surface-family="${type}" ${choices.some(c=>c.tipo===type&&selected.has(c.id))?'open':''}><summary>${({muros:'Muros',cielos:'Cielos',pavimentos:'Pavimentos',recinto:'Alcances anteriores'})[type]}</summary>${choices.filter(s=>s.tipo===type).map(s=>`<label class="check"><input type="checkbox" data-choice="${esc(s.id)}" ${selected.has(s.id)?'checked':''}>${esc(s.orientation?'Muro '+s.orientation.label:s.label)}</label>`).join('')||'<small>Sin elementos identificados.</small>'}</details>`).join('')}<label>Condición del cielo<select data-ceiling>${['Sin información verificada','Proyectado, pendiente de ejecución','Existente según supervisor','Inexistente'].map(v=>`<option ${v===original.find(s=>s.tipo==='cielos')?.availability?'selected':''}>${v}</option>`).join('')}</select></label><label>Solución de cielo<select data-ceiling-kind>${['Sin información verificada','Cielo falso','Losa expuesta','Otra solución'].map(v=>`<option ${v===original.find(s=>s.tipo==='cielos')?.solution?'selected':''}>${v}</option>`).join('')}</select></label><p role="alert"></p><button type="button" data-cancel>Cancelar</button><button type="button" data-apply>Aplicar cambios</button>`;
 const ceilingOptions=()=>{const chosen=[...editor.querySelectorAll('[data-choice]:checked')].some(el=>choices.find(c=>c.id===el.dataset.choice)?.tipo==='cielos');editor.querySelector('[data-ceiling]').closest('label').hidden=!chosen;editor.querySelector('[data-ceiling-kind]').closest('label').hidden=!chosen;};ceilingOptions();editor.onchange=()=>{dirty=true;ceilingOptions();};editor.querySelector('[data-cancel]').onclick=()=>{editing=null;dirty=false;editor.replaceChildren();};editor.querySelector('[data-apply]').onclick=()=>{const ids=new Set([...editor.querySelectorAll('[data-choice]:checked')].map(el=>el.dataset.choice)),availability=editor.querySelector('[data-ceiling]').value;let updated=choices.filter(s=>ids.has(s.id)).map(s=>({...s,locationOnly:false,...(s.tipo==='cielos'?{availability,solution:editor.querySelector('[data-ceiling-kind]').value}:{} )}));if(updated.some(s=>s.tipo==='cielos')&&availability==='Inexistente'){editor.querySelector('[role=alert]').textContent='Un cielo inexistente no puede seleccionarse. Define una actividad futura solo si existe un elemento proyectado.';return;}if(!updated.length)updated=(boundaries.length?boundaries:[null]).map((g,i)=>({...base,id:base.roomId+'|location|'+i,tipo:'recinto',geometry:g,roomBoundary:g,roomBoundaries:boundaries,locationOnly:true,label:'Pendiente de definir superficies',measurement:null}));if(updated.some(s=>s.tipo==='cielos')&&availability==='Proyectado, pendiente de ejecución')onPending(base,updated.filter(s=>s.tipo==='cielos'));editing=null;dirty=false;let inserted=false;set(get().flatMap(s=>s.roomId!==id?[s]:inserted?[]:(inserted=true,updated)));render();};
 }
 return {render,pending:()=>dirty};
}
